import 'package:flutter/material.dart';import 'package:sehatak/core/models/pregnancy/pregnancy_models.dart';import 'package:sehatak/core/services/pregnancy_service.dart';class PregnancyTipsScreen extends StatelessWidget{const PregnancyTipsScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('نصائح الحمل')),body:StreamBuilder<List<PregnancyTip>>(stream:PregnancyService().streamTips(limit:30),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((d)=>Card(child:ExpansionTile(leading:const Icon(Icons.lightbulb_outline,color:Color(0xFFE91E63)),title:Text(d.title),subtitle:Text('${d.category}${d.week==null?'':' • الأسبوع ${d.week}'}'),children:[Padding(padding:const EdgeInsets.all(16),child:Text(d.body))]))).toList());}));}}
